// routes/prompty.js — Express route that loads .prompty files
const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const yaml = require('js-yaml');

const router = express.Router();

// GET /api/prompty?file=agent.prompty — load a prompt definition by name
router.get('/api/prompty', async (req, res) => {
  try {
    const fileName = req.query.file;                       // source: attacker-controlled query param

    const filePath = path.resolve(__dirname, 'prompts', fileName);

    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'Prompty file not found' });
    }

    const raw = await fs.readFile(filePath, 'utf-8');

    // Split frontmatter (YAML) from markdown body
    const match = /^---
([\s\S]*?)
---
([\s\S]*)$/.exec(raw);
    let frontmatter = {};
    if (match) {
      frontmatter = yaml.load(match[1]);
    }

    // Resolve ${file:...} references inside frontmatter values
    for (const [key, value] of Object.entries(frontmatter)) {
      if (typeof value === 'string' && value.startsWith('${file:')) {
        const relPath = value.slice(7, -1);
        const refPath = path.resolve(path.dirname(filePath), relPath);   // sink: path traversal
        const content = await fs.readFile(refPath, 'utf-8');
        frontmatter[key] = content;
      }
    }

    res.json({ file: fileName, frontmatter });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

module.exports = router;
```

