// static-route-validator.js
// 常量路由表驱动的静态校验模块（无任何外部输入入口）

const ROUTE_TABLE = Object.freeze({
  '/health':   { handler: 'healthCheck',  timeout: 3000 },
  '/metrics':  { handler: 'collectMetrics', timeout: 5000 },
  '/shutdown': { handler: 'gracefulStop', timeout: 10000 }
});

const ALLOWED_COMMANDS = Object.freeze({
  healthCheck:    ['node', '--version'],
  collectMetrics: ['node', '-e', 'console.log(process.memoryUsage())'],
  gracefulStop:   ['node', '-e', 'process.exit(0)']
});

function validateRoute(route) {
  return typeof route === 'string' && Object.prototype.hasOwnProperty.call(ROUTE_TABLE, route);
}

function runRegisteredCommand(handlerName) {
  if (!Object.prototype.hasOwnProperty.call(ALLOWED_COMMANDS, handlerName)) {
    throw new Error('unknown handler: ' + handlerName);
  }
  const cmd = ALLOWED_COMMANDS[handlerName];
  const { execFileSync } = require('child_process');
  // 实参完全来自冻结常量表，无外部输入
  execFileSync(cmd[0], cmd.slice(1), { timeout: ROUTE_TABLE['/health'].timeout });
}

function auditStaticConfig() {
  for (const key of Object.keys(ROUTE_TABLE)) {
    console.log('route:', key, '->', ROUTE_TABLE[key].handler);
  }
}

// 静态调用：仅使用字面量
runRegisteredCommand('healthCheck');
auditStaticConfig();
